CREATE VIEW hiring_stage_checks_v3 AS
SELECT kind,organization_id,brand_id,requisition_id,application_id,actor_user_id,actor_id,actor_role,expected_version,from_stage,to_stage,operation_id,reason FROM hiring_mutation_checks WHERE 0;

CREATE TRIGGER hiring_stage_check_v3 INSTEAD OF INSERT ON hiring_stage_checks_v3 BEGIN
 SELECT RAISE(ABORT,'APP:not_found') WHERE NOT EXISTS(SELECT 1 FROM hiring_applications a WHERE a.id=NEW.application_id AND a.organization_id=NEW.organization_id AND a.brand_id=NEW.brand_id);
 SELECT RAISE(ABORT,'APP:forbidden') WHERE NEW.actor_user_id IN ('system','automation','api_key','system:worker') OR NOT EXISTS(SELECT 1 FROM hiring_applications a JOIN hiring_effective_access g ON g.organization_id=a.organization_id AND g.brand_id=a.brand_id AND g.user_id=NEW.actor_user_id AND g.role IN ('owner','recruiter') AND (g.requisition_id IS NULL OR g.requisition_id=a.requisition_id) WHERE a.id=NEW.application_id AND a.organization_id=NEW.organization_id AND a.brand_id=NEW.brand_id);
 SELECT RAISE(ABORT,'APP:duplicate_operation_id') WHERE EXISTS(SELECT 1 FROM hiring_stage_events WHERE id=NEW.operation_id) AND NOT EXISTS(SELECT 1 FROM hiring_stage_events e WHERE e.id=NEW.operation_id AND e.organization_id=NEW.organization_id AND e.brand_id=NEW.brand_id AND e.application_id=NEW.application_id AND e.actor_user_id=NEW.actor_user_id AND e.from_stage=NEW.from_stage AND e.to_stage=NEW.to_stage AND e.version=NEW.expected_version+1 AND e.reason=NEW.reason);
 SELECT RAISE(IGNORE) WHERE EXISTS(SELECT 1 FROM hiring_stage_events e WHERE e.id=NEW.operation_id AND e.organization_id=NEW.organization_id AND e.brand_id=NEW.brand_id AND e.application_id=NEW.application_id AND e.actor_user_id=NEW.actor_user_id AND e.from_stage=NEW.from_stage AND e.to_stage=NEW.to_stage AND e.version=NEW.expected_version+1 AND e.reason=NEW.reason);
 SELECT RAISE(ABORT,'APP:version_mismatch') WHERE NOT EXISTS(SELECT 1 FROM hiring_applications a WHERE a.id=NEW.application_id AND a.version=NEW.expected_version AND COALESCE(a.workflow_stage,a.lifecycle_stage,a.accepted_stage,a.stage_extension,a.stage)=NEW.from_stage);
 SELECT RAISE(ABORT,'APP:invalid_transition') WHERE NOT ((NEW.from_stage='submitted' AND NEW.to_stage IN ('in_review')) OR (NEW.from_stage='in_review' AND NEW.to_stage IN ('shortlisted','rejected','interviewing')) OR (NEW.from_stage='shortlisted' AND NEW.to_stage IN ('offered','rejected','interviewing')) OR (NEW.from_stage='offered' AND NEW.to_stage IN ('hired','rejected')) OR (NEW.from_stage='interviewing' AND NEW.to_stage IN ('decision_pending')) OR (NEW.from_stage='decision_pending' AND NEW.to_stage IN ('offered','rejected')));
 SELECT RAISE(ABORT,'reason and operation_id required') WHERE length(trim(COALESCE(NEW.reason,'')))=0 OR length(trim(NEW.operation_id))=0;
 SELECT RAISE(ABORT,'approved offer required for offered or hired') WHERE NEW.to_stage IN ('offered','hired') AND NOT EXISTS(SELECT 1 FROM hiring_offers o WHERE o.application_id=NEW.application_id AND o.tenant_id=NEW.organization_id AND o.brand_id=NEW.brand_id AND o.status='approved');
 SELECT RAISE(IGNORE);
END;
